local _, ns = ...
local L = ns.locales.enUS
L.helpTour = "Tour"
L.helpTourTip = "A step-by-step look at markets and buttons over the window."
L.helpWiki = "Market guide"
L.helpWikiTip = "What each market calculates, where prices come from, how and when to refresh them."
L.wikiTitle = "Market guide"
L.wikiHeadAbout = "What it is about"
L.wikiHeadPrices = "Where prices come from"
L.wikiHeadMath = "How it is calculated"
L.wikiHeadRefresh = "How to refresh"
L.wikiHeadKeep = "What is kept and for how long"
L.wikiHeadBest = "What works best when"
L.wikiKeepScans = "Every search is kept for about %d days, then the oldest go."
L.wikiKeepFull = "The latest full picture of your realm and faction market is always kept."
L.wikiKeepChart = "The \"Market\" window remembers item prices for up to %d days."
L.wikiKeyBargainSoft = "Not checked for longer than the freshness window."
L.wikiKeyBargainHard = "Every item of the group."
L.wikiKeyBuy = "\"Search\" - always fresh."
L.wikiAbout_processing = "Which pays more: sell as is or process and sell the result.\nDisenchanting - gear into dust, essences and shards; \"Disenchant target\" - which gear yields the material you need.\nProspecting and Milling - ore into gems, herbs into pigments, 5 per operation.\nEssences and elementals - lesser and greater 3:1, elementals and motes 10:1."
L.wikiPrices_processing = "Material and raw prices come from your searches with the screen buttons.\nGear for disenchanting is searched as a whole gear category.\nYields are averages by chance: one operation can go worse or better."
L.wikiRefresh_processing = "\"Complete\" buttons are at the bottom; \"Gear\" in Disenchanting searches anew on any click."
L.wikiKeep_processing = "Your own prices of disenchant materials are not replaced by searches."
L.wikiBest_processing = "Lots of cheap gear - Disenchanting by gear.\nNeed a specific material - \"Disenchant target\" or Prospecting, and compare with buying.\nLesser and greater essences off the 3:1 ratio - Essences and elementals."
L.wikiAbout_professions = "Pick a profession in the menu, then a mode.\nCraft - recipes by margin, the Batch on the right plans a run.\nResources - ore, herbs, leather and fish: price and processing profit.\nLeveling - a skill route with a reagent basket (Enchanting and Alchemy).\nNPC recipes - vendor formulas to resell."
L.wikiPrices_professions = "Products and reagents come from your recipe searches.\nReagents sold by a vendor use the vendor price and are not searched on the auction."
L.wikiRefresh_professions = "\"Complete profession\" gathers prices of all recipes and nested reagents in one click.\nA single row is refreshed by its icon."
L.wikiKeep_professions = "Favorite recipes stay pinned on top until you remove them."
L.wikiBest_professions = "Looking for something to craft and sell - Craft: the most profitable are on top.\nGathering skill - Resources: sell as is or process.\nLeveling a skill - Leveling, then buy the basket in \"Buy\"."
L.wikiAbout_materials = "From a material to its uses: sell as is, craft, process or exchange.\n\"All\" - materials of every catalog, \"In bags\" - what is in this character's bags.\nOn the right - what to do with the material and the \"Post\" form."
L.wikiPrices_materials = "Market per unit comes from your searches; a vendor price is not a market price.\nCost of bag items comes from Accounting when every batch price is known."
L.wikiRefresh_materials = "\"Complete uses\" in \"All\", \"Complete bags\" in \"In bags\"."
L.wikiBest_materials = "Sorting bags - \"In bags\": what to sell and for how much at a glance.\nDeciding where a material goes - \"All\" and the \"What to do\" block."
L.wikiAbout_bargain = "A watch list: raid epics, mounts and pets, rare recipes and reagents, plus your own items.\nFinds lots cheaper than the usual price where resale stays profitable.\nA lot below the vendor price is marked: buy it and sell it to an NPC right away."
L.wikiPrices_bargain = "Lots come from \"Complete\" searches by item name.\nUsual price - the first available: yours, the median of checks over %d days (at least %d needed) or the market of current lots."
L.wikiRefresh_bargain = "Up to %d searches per click, the longest unchecked first; the rest go with the next click."
L.wikiKeep_bargain = "Your list, hidden items and your own item prices are kept until you remove them."
L.wikiBest_bargain = "Spare gold - \"Deals\" after \"Complete\".\nYour own resale goods - \"My list\" with the \"Add\" field."
L.wikiAbout_seasonal = "Holiday goods: quests, achievements and holiday crafting.\nThe holiday is picked at the top; dates come from the game calendar.\n\"Sold by NPC\" - a vendor sells it, no auction needed."
L.wikiPrices_seasonal = "Prices come from \"Complete holiday\" and row icons.\nThe table price is the auction price even for vendor goods: for comparison."
L.wikiRefresh_seasonal = "\"Complete holiday\" is on the right of the holiday header."
L.wikiBest_seasonal = "Dates tell when the goods are wanted: check prices ahead of time.\n\"Buy on the auction\" in the panel opens a search for one use."
L.wikiAbout_npc = "NPC trading - buy from a vendor for gold or items and sell on the auction.\nCurrency - what to buy with emblems, honor, badges and Frozen Orbs.\nNPC recipes - vendor formulas to resell.\nOnly tradable goods and vendors of your faction or neutral ones."
L.wikiPrices_npc = "The vendor price comes from the addon vendor list, the auction price from your searches.\nAn exchange costs the auction prices of what you pay with."
L.wikiRefresh_npc = "\"Complete\" at the bottom - goods of the open segment; \"Auction\" searches the selected good in \"Buy\"."
L.wikiBest_npc = "Currency piling up - \"Currency\": revenue per unit at a glance.\nGold but little time - NPC trading: buy from a vendor and post."
L.wikiAbout_collections = "Favorite recipes and tracked items in one place.\nAdd an item by name, ID or link here or with the star in the item panel.\nFavorites are pinned on top of the profession list."
L.wikiPrices_collections = "Prices come from \"Complete list\" and row icons; price and check time are shown separately."
L.wikiRefresh_collections = "\"Complete list\" refreshes the items of the open list."
L.wikiKeep_collections = "Lists are kept until you remove an item."
L.wikiBest_collections = "Watching a dozen goods - keep them here and refresh in one click."
L.wikiAbout_hidden = "Items and groups removed from the working lists of every screen.\nFilters by profession and recipe category; \"Restore all\" follows the current filter."
L.wikiPrices_hidden = "Hidden items are not searched and stay out of best picks."
L.wikiRefresh_hidden = "Nothing to refresh here: restore an item and its prices are searched again."
L.wikiKeep_hidden = "Hiding is kept until you restore the item."
L.wikiBest_hidden = "Hide what does not sell or is not needed: fewer searches."
L.wikiAbout_accounting = "Chains \"input - processing - output - sale\": disenchanting, prospecting, milling, crafting and resale.\nItems, Materials, Journal, Analysis and Forecast are views of the same records.\n\"New batch\" starts a new count, nothing old is deleted."
L.wikiPrices_accounting = "Records are written by themselves: purchases, mail, processing, crafting, posting and sale money.\nStock is valued at current auction prices after the fee."
L.wikiRefresh_accounting = "Accounting searches nothing itself; \"Complete forecast\" covers batch stock and forecast recipe products."
L.wikiKeep_accounting = "The journal of purchases, sales and disenchanting is kept whole and never deleted.\n\"Track everything\" records any buyout, not only catalog goods."
L.wikiBest_accounting = "Start a batch before a new run to see its result separately."
L.wikiAbout_buy = "Find an item by name and buy the amount needed or everything cheaper than your price.\n\"Amount needed\" is how many to buy, \"Under, per item\" the highest price per item.\nBuyouts only by click; before each the lot is found again and its price checked."
L.wikiPrices_buy = "Only a fresh search of this item: every \"Search\" reads the lots anew.\nThe panel on the right: current prices and the 7-day median of past searches."
L.wikiRefresh_buy = "New lots appear only after a new search."
L.wikiKeep_buy = "Recent - up to %d items over %d days, with the last amount and the previous purchase."
L.wikiBest_buy = "The buy icon in rows of other screens opens a search of that item here.\n\"Up to last price\" sets the limit from the previous purchase."
L.wikiAbout_sell = "What in your bags is worth selling and for how much, posting in stacks.\n\"My auctions\" - your lots against others and cancelling."
L.wikiPrices_sell = "Prices come from \"Complete bags\" and \"Complete my auctions\".\nThe auction sends your own lots by itself: on opening and after posting."
L.wikiRefresh_sell = "The complete button is at the right edge of the table, one per view."
L.wikiBest_sell = "Refresh bag prices before posting so you do not sell below the market."
